/** user-defined types **/

/**
 * Blame information for a file at HEAD.
 */
export type Blame = { path: string; lines: string[]; hunks: BlameHunk[] }
/**
 * A run of consecutive lines last changed by the same commit.
 */
export type BlameHunk = { 
/**
 * 1-based first line of the hunk in the current file.
 */
startLine: number; lineCount: number; commitId: string; shortId: string; author: string; timestamp: number; summary: string }
/**
 * A local or remote-tracking branch.
 */
export type Branch = { name: string; fullName: string; isRemote: boolean; isHead: boolean; target: string; 
/**
 * For remote branches, the remote name (`origin`).
 */
remote: string | null; 
/**
 * Short name of the upstream of a local branch (`origin/main`).
 */
upstream: string | null; 
/**
 * True when the configured upstream no longer exists.
 */
upstreamGone: boolean; ahead: number; behind: number; summary: string; timestamp: number }
/**
 * How a file changed between two snapshots.
 */
export type ChangeKind = "added" | "deleted" | "modified" | "renamed" | "copied" | "typeChange" | "untracked" | "conflicted"
/**
 * Which parts of the repository changed in a batch of events.
 */
export type ChangeSet = { 
/**
 * Files in the working tree.
 */
workdir: boolean; 
/**
 * The index (staging area).
 */
index: boolean; 
/**
 * HEAD, branches, tags, stashes or the operation state (merge…).
 */
refs: boolean }
/**
 * Everything shown in the commit detail panel.
 */
export type CommitDetail = { id: string; shortId: string; summary: string; 
/**
 * Message body without the summary line; empty when absent.
 */
body: string; author: Signature; committer: Signature; parents: string[]; refs: RefLabel[]; files: FileChange[]; stats: DiffStats; 
/**
 * True when the file list was capped for very large commits.
 */
filesTruncated: boolean }
/**
 * The lightweight view of a commit used in lists and the graph.
 */
export type CommitSummary = { id: string; shortId: string; summary: string; author: Signature; parents: string[] }
/**
 * A file with unresolved merge conflicts.
 */
export type ConflictFile = { path: string; 
/**
 * False when "ours" deleted the file.
 */
hasOurs: boolean; 
/**
 * False when "theirs" deleted the file.
 */
hasTheirs: boolean }
/**
 * Side of a conflict to keep when resolving a file.
 */
export type ConflictSide = "ours" | "theirs"
/**
 * A single line of a hunk. `content` never includes the trailing newline.
 */
export type DiffLine = { kind: LineKind; oldLine: number | null; newLine: number | null; content: string; 
/**
 * True when the line is followed by "\ No newline at end of file".
 */
noNewline: boolean }
/**
 * Aggregated line statistics of a diff.
 */
export type DiffStats = { filesChanged: number; additions: number; deletions: number }
/**
 * Stable, machine readable error codes.
 */
export type ErrorCode = "NOT_A_REPOSITORY" | "PATH_NOT_FOUND" | "REPO_NOT_OPEN" | "INVALID_INPUT" | "NOT_FOUND" | "NOTHING_TO_COMMIT" | "IDENTITY_MISSING" | "WOULD_OVERWRITE_CHANGES" | "BRANCH_NOT_MERGED" | "ALREADY_EXISTS" | "UNRESOLVED_CONFLICTS" | "STALE_DIFF" | "STALE_GRAPH" | "UNSAFE_OPERATION" | "CANCELLED" | "GIT_NOT_FOUND" | "GIT_COMMAND_FAILED" | "GIT" | "IO"
/**
 * The serialised form of an [`Error`] sent across the IPC boundary.
 */
export type ErrorPayload = { code: ErrorCode; message: string; 
/**
 * Extra technical detail (e.g. the failing git command), if any.
 */
detail: string | null }
/**
 * A changed file inside a commit, the index or the working tree.
 */
export type FileChange = { path: string; 
/**
 * Previous path for renames and copies.
 */
oldPath: string | null; kind: ChangeKind; additions: number; deletions: number; binary: boolean }
/**
 * The diff of one file.
 */
export type FileDiff = { path: string; oldPath: string | null; kind: ChangeKind; binary: boolean; hunks: Hunk[]; 
/**
 * True when the diff was cut short because it was too large to display.
 */
truncated: boolean }
/**
 * One commit in the history of a single file.
 */
export type FileHistoryEntry = { commit: CommitSummary; change: ChangeKind; 
/**
 * The path the file had in this commit.
 */
path: string }
/**
 * A line segment of the commit graph.
 * 
 * Every edge belongs to the row it ends in: it starts at the vertical centre
 * of the previous row in column `from` and ends at the centre of its own row
 * in column `to`. A row therefore owns all the lines entering it from above,
 * which keeps pagination trivial: drawing rows `a..b` only needs edges of
 * those rows (plus row `b` for the half-segment leaving the last one).
 */
export type GraphEdge = { from: number; to: number; color: number }
/**
 * Metadata about the whole graph, used to size the virtual list.
 */
export type GraphInfo = { total: number; maxColumns: number; 
/**
 * Changes whenever any ref moves; part of the frontend cache key.
 */
fingerprint: string; 
/**
 * Row of the commit HEAD points to, if it is part of the graph.
 */
headRow: number | null; headId: string | null }
/**
 * One row of the commit graph: a commit plus how to draw it.
 */
export type GraphRow = { index: number; commit: CommitSummary; refs: RefLabel[]; column: number; color: number; edges: GraphEdge[]; isMerge: boolean }
/**
 * Where HEAD points.
 */
export type HeadInfo = { 
/**
 * Short name of the current branch; `None` when detached.
 */
branch: string | null; detached: boolean; 
/**
 * The commit HEAD resolves to; `None` on an unborn branch.
 */
target: string | null; 
/**
 * True right after `git init`, before the first commit.
 */
unborn: boolean }
/**
 * A contiguous block of changes with its surrounding context.
 */
export type Hunk = { header: string; oldStart: number; oldLines: number; newStart: number; newLines: number; lines: DiffLine[] }
/**
 * Identifies a hunk the UI wants to act on (stage, unstage, discard).
 * 
 * The ranges are compared against a freshly computed diff so that an action
 * on a stale view is rejected instead of touching the wrong lines.
 */
export type HunkRef = { index: number; oldStart: number; oldLines: number; newStart: number; newLines: number }
/**
 * The kind of a single diff line.
 */
export type LineKind = "context" | "added" | "deleted"
/**
 * Options for `merge`.
 */
export type MergeOptions = { 
/**
 * Always create a merge commit, even when a fast-forward is possible.
 */
noFf: boolean }
/**
 * Outcome of a merge (or of the merge step of a pull).
 */
export type MergeOutcome = { type: "upToDate" } | { type: "fastForward"; head: string } | { type: "merged"; commit: CommitSummary } | { type: "conflicts"; files: ConflictFile[] }
/**
 * The result of a mutation, possibly undoable.
 */
export type Mutation<T> = { value: T; undo: UndoHandle | null }
/**
 * Progress of a long-running operation (clone, fetch, pull, push).
 */
export type Progress = { 
/**
 * Phase reported by git, e.g. "Receiving objects".
 */
phase: string; 
/**
 * Percentage of the current phase, when git reports one.
 */
percent: number | null; 
/**
 * The raw progress line, for display.
 */
message: string }
/**
 * Options for `push`.
 */
export type PushOptions = { 
/**
 * Remote to push to when the branch has no upstream yet.
 */
remote: string | null; forceWithLease: boolean }
/**
 * An entry of the "recent repositories" list.
 */
export type RecentRepo = { name: string; path: string; 
/**
 * Seconds since the Unix epoch.
 */
lastOpened: number; 
/**
 * False when the folder no longer exists or is not a repository.
 */
available: boolean }
/**
 * The namespace a reference lives in.
 */
export type RefKind = "localBranch" | "remoteBranch" | "tag" | 
/**
 * A detached HEAD.
 */
"head"
/**
 * A reference decorating a commit in the graph or the detail panel.
 */
export type RefLabel = { 
/**
 * Short name such as `main`, `origin/main` or `v1.0`.
 */
name: string; 
/**
 * Full name such as `refs/heads/main`.
 */
fullName: string; kind: RefKind; 
/**
 * True for the branch HEAD points to (or the detached HEAD itself).
 */
isHead: boolean }
/**
 * A configured remote.
 */
export type Remote = { name: string; fetchUrl: string | null; pushUrl: string | null }
/**
 * Summary of a network operation, shown in the result notification.
 */
export type RemoteOutcome = { 
/**
 * Condensed, human readable output of git.
 */
message: string; 
/**
 * Set by `pull` when the merge/rebase step stopped on conflicts.
 */
conflicts: ConflictFile[] }
/**
 * Something changed on disk in an open repository.
 */
export type RepoChanged = { repoId: string; changes: ChangeSet }
/**
 * Summary of an open repository.
 */
export type RepoInfo = { id: string; name: string; path: string; head: HeadInfo; state: RepoState }
/**
 * An operation that is in progress and must be finished or aborted.
 */
export type RepoState = "clean" | "merging" | "rebasing" | "cherryPicking" | "reverting" | "bisecting" | "applyingMailbox"
/**
 * What a reset does to the index and the working tree.
 */
export type ResetMode = 
/**
 * Move the branch only; changes stay staged.
 */
"soft" | 
/**
 * Move the branch and reset the index; changes stay in the working tree.
 */
"mixed" | 
/**
 * Move the branch and discard all changes.
 */
"hard"
/**
 * Which commit field a search query is matched against.
 */
export type SearchField = "all" | "message" | "author" | "hash"
/**
 * Author or committer identity together with the moment it was recorded.
 */
export type Signature = { name: string; email: string; 
/**
 * Seconds since the Unix epoch.
 */
timestamp: number; 
/**
 * Offset from UTC in minutes.
 */
offsetMinutes: number }
/**
 * A stash entry. `index` is its position in `stash@{n}`.
 */
export type Stash = { index: number; id: string; message: string; 
/**
 * The branch the stash was created on, parsed from its message.
 */
branch: string | null; timestamp: number }
/**
 * A tag, peeled to the commit it marks.
 */
export type Tag = { name: string; target: string; annotated: boolean; message: string | null; tagger: Signature | null }
/**
 * Handle to the last undoable operation, returned alongside its result.
 */
export type UndoHandle = { id: number; 
/**
 * Human readable description, e.g. "Commit a1b2c3d".
 */
label: string }
/**
 * The state of the index and the working tree.
 */
export type WorkingTreeStatus = { staged: FileChange[]; unstaged: FileChange[]; conflicted: ConflictFile[]; state: RepoState }

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
